import numpy as np
def equation(t, P, params):
    a0,a1,a2,b0,b1,b2,K,n,c0,c1 = params
    S = t**n/(np.abs(K)**n + t**n)
    return (a0+a1*P+a2*P**2)*S + (b0+b1*P+b2*P**2) + t*(c0+c1*P)
